function updateHud(){const p=game.player;const lifeText=`${'♥'.repeat(p.lives)}${'♡'.repeat(5-p.lives)} · ${p.lives} / 5 LIVES`;if($('lives').textContent!==lifeText)$('lives').textContent=lifeText;const rosterKey=game.fighters.map(f=>`${f.lives}:${f.alive}:${f.respawn>0}`).join('|');if(rosterKey!==lastLifeRoster){lastLifeRoster=rosterKey;$('life-roster').innerHTML=game.fighters.map(f=>`<div class="life-entry ${!f.alive?'out':''}" style="--fighter:${FIGHTERS[f.baseType].color}"><strong>${f.id===0?'YOU':FIGHTERS[f.baseType].name}</strong><span>${f.alive?(f.respawn>0?'RESPAWN · ':'')+f.lives+' / 5':'ELIMINATED'}</span></div>`).join('');}$('hp').textContent=`${Math.ceil(Math.max(0,p.hp))} / ${p.maxHp} HP`;$('health').style.width=`${Math.max(0,p.hp)/p.maxHp*100}%`;$('loot-status').innerHTML=`${p.starTime>0?`<span class="star-active">★ INVINCIBLE · ${p.starTime.toFixed(1)}s · F ATTACK</span>`:p.flowerShots>0?`<span class="flower-active">✿ ${p.flowerShots} / 5 FIREBALLS · F SHOOT</span>`:`<span class="item-ready">R: ${selectedItem==='star'&&p.starUsed?'STAR USED THIS ROUND':flowerInventory.countOf(selectedItem)>0?ITEM_NAMES[selectedItem]:'NO SAVED ITEM'}</span>`}<span class="ring-total">◉ ${p.rings} RINGS${p.haste>0?' · SPEED '+Math.ceil(p.haste)+'s':''}</span>${p.armor>0?`<span style="color:${ARMORS[p.armorType].color}">▣ ${ARMORS[p.armorType].name} ARMOR · ${Math.ceil(p.armor)}</span>`:''}${p.sizeTime>0?`<span class="size-total">SIZE ×${p.size} · ${Math.ceil(p.sizeTime)}s</span>`:''}`;$('damage').textContent=`${Math.round(p.damage)}% KNOCKBACK`;$('hud-name').textContent=p.copyTime>0?`KOBALT / ${FIGHTERS[p.type].name}`:FIGHTERS[p.type].name;$('hud-name').style.color=FIGHTERS[p.type].color;$('health').style.background=FIGHTERS[p.type].color;document.querySelector('[data-action=fire]').textContent=p.zombie>0||p.type===8?'BITE':p.type===9?'ATOMIC':p.unicorn>0?'CHARGE':p.type===5?'SLASH':'FIRE';document.querySelector('[data-action=flower]').hidden=p.flowerShots===0&&p.starTime===0;document.querySelector('[data-action=flower]').textContent=p.starTime>0?'FIGHT (F)':'FIREBALL (F)';if(!p.alive)$('touch').hidden=true;$('ability').textContent=!p.alive?'ELIMINATED · WATCHING THE FINAL FIGHT':p.respawn>0?`RESPAWNING · ${p.respawn.toFixed(1)}s`:p.type===5&&p.scared>0?'SCARED OF CATS · FIRE DISABLED':p.zombie>0?'ZOMBIE DOG ALLY · X TO BITE':p.unicorn>0?'UNICORN ALLY · X TO CHARGE':`[Z] ${FIGHTERS[p.type].power.toUpperCase()} · ${p.inhale>0?'INHALING':p.cool>0?Math.ceil(p.cool)+'s':'READY'}${p.copyTime>0?' · COPY '+Math.ceil(p.copyTime)+'s':''}`;$('alive').textContent=game.fighters.filter(f=>f.alive).length;$('clock').textContent=`${Math.floor(game.time/60).toString().padStart(2,'0')}:${Math.floor(game.time%60).toString().padStart(2,'0')}`;$('zone-label').textContent=game.time<18?`ZONE CLOSES IN ${Math.ceil(18-game.time)}s`:'DANGER ZONE SHRINKING';$('feed').textContent=game.feed.join('\n');$('pickup-status').textContent=!p.alive?'LAST FIGHTER STANDING WINS':game.finalShowdown?'FINAL SHOWDOWN · NO RECRUITING':p.type===5&&p.scared>0?'MOVE AWAY FROM THE CAT!':p.zombie>0?'YOU JOINED THE ZOMBIE PACK!':p.unicorn>0?'YOU ARE FARTING GLITTER!':p.haste>0?`RING RUSH · ${Math.ceil(p.haste)}s`:game.army(p).length?`${game.army(p).some(f=>f.zombie>0)?'ZOMBIE PACK':'UNICORN ARMY'}: ${game.army(p).length} · AIM + Q TO COMMAND`:p.type===8?'TOUCH RIVALS TO GROW YOUR ZOMBIE PACK':p.type===7?'TOUCH RIVALS TO RECRUIT YOUR ARMY':p.swimming?`SWIMMING · HOLD L · ${p.air<4?'AIR '+Math.ceil(p.air)+'s':'SPACE TO LEAP'}`:p.climbing?'CLIMBING · SPACE TO JUMP OFF':p.boost>0?`RAPID FIRE · ${Math.ceil(p.boost)}s`:p.shield>0?'SHIELDED':'';}
function finish(){const earned=flowerInventory.award(matchId,game.playerIsChampion);$('flower-award').hidden=!game.playerIsChampion;if(game.playerIsChampion){lastAwardType=earned||flowerInventory.awardType(matchId)||'flower';$('flower-award-icon').innerHTML=lastAwardType==='star'?starIcon:flowerIcon;$('flower-award-title').textContent=`FIRST PLACE · +1 ${ITEM_NAMES[lastAwardType]}`;$('flower-award-stock').textContent=`${flowerInventory.total} saved · next win: ${ITEM_NAMES[flowerInventory.nextReward]}`;$('flower-award-choice').textContent='Saved automatically. Select an item, then press R in a round.';}updateFlowerBank();const won=game.won,podium=game.podium,champion=podium?FIGHTERS[podium.winnerType]:null;$('winner-trophy').hidden=!podium;document.querySelector('.result').classList.toggle('has-trophy',!!podium);if(podium)$('winner-trophy').innerHTML=victoryTrophy(FIGHTERS[podium.winnerType],FIGHTERS[podium.loserType]);$('overlay').hidden=false;$('touch').hidden=true;$('result-label').textContent=won?'FIRST PLACE · LAST FIGHTER STANDING':champion?`${champion.name} · LAST FIGHTER STANDING`:'DRAW · NO FIGHTERS LEFT';$('result-title').innerHTML=won?'LAST STICK<br>STANDING.':champion?`${champion.name}<br>WINS.`:'DOUBLE<br>KNOCKOUT.';$('result-desc').textContent=`${game.knockouts} KOs · ${game.kills} elimination${game.kills===1?'':'s'} · ${Math.floor(game.time)} seconds survived · ${FIGHTERS[choice].name}`;$('again').textContent='RUN IT BACK';tone(won?800:180,.5,'sine',.05);}
function frame(now){const dt=Math.min((now-last)/1000,.035);last=now;if(game&&!paused&&!game.over){let p=game.player;let aim=pointer.used&&!touch?Math.atan2(pointer.y-(p.y-30*p.size),pointer.x-p.x):p.face>0?0:Math.PI;if(touch||keys.KeyX||(pressed.KeyZ&&p.type===6)){const target=game.fighters.filter(f=>game.active(f)&&f.id!==0&&!game.allied(f,p)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(target)aim=Math.atan2((target.y-30*target.size)-(p.y-30*p.size),target.x-p.x);}if(pressed.KeyR)activateSavedItem();if(pressed.KeyQ){const target=game.fighters.filter(f=>game.active(f)&&!game.allied(f,p)).sort((a,b)=>Math.hypot(a.x-(pointer.used?pointer.x:p.x),a.y-30-(pointer.used?pointer.y:p.y-30))-Math.hypot(b.x-(pointer.used?pointer.x:p.x),b.y-30-(pointer.used?pointer.y:p.y-30)))[0];if(target)game.commandArmy(p,target.id);}const aimX=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),aimY=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);const manualItemAim=pointer.used?Math.atan2(pointer.y-(p.y-30*p.size),pointer.x-p.x):(aimX||aimY)?Math.atan2(aimY,aimX):p.face>0?0:Math.PI;game.update(dt,{move:(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),jump:pressed.Space||((pressed.KeyW||pressed.ArrowUp)&&!game.vines.some(v=>Math.abs(v.x-p.x)<32&&p.y>=v.top-8&&p.y-50<=v.bottom)),climb:(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),fire:pointer.down||keys.KeyX,flower:keys.KeyF,itemAim:manualItemAim,special:pressed.KeyZ,swim:keys.KeyL,aim});if(game.bullets.length>previousBullets)tone(220,.045);previousBullets=game.bullets.length;updateHud();if(game.over)finish();}pressed={};draw(now/1000);requestAnimationFrame(frame);}requestAnimationFrame(frame);
